/* eslint-disable max-len */

'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var currentYear = require( '@stdlib/time/current-year' );
var append = require( '@stdlib/utils/append' );
var DATA = require( '@stdlib/math/special/data/unary.json' );
var FUNCTION_DATABASE = require( '@stdlib/math/special/data/unary_function_database.json' );
var escapeBashString = require( './escape_bash_string.js' );
var prngEnvVars = require( './prng_env_vars.js' );
var aliasEnvVar = require( './alias_env_var.js' );
var pkgEnvVar = require( './pkg_env_var.js' );
var assignDescEnvVar = require( './assign_desc_env_var.js' );
var pkgDepsEnvVar = require( './pkg_deps_env_var.js' );
var generateTemplateVars = require( './generate_template_vars.js' );
var jsExampleEnvVars = require( './js_example_env_vars.js' );
var ndarrayEnvVars = require( './ndarray_env_vars.js' );
var readmeEnvVars = require( './readme_env_vars.js' );
var policyEnvVars = require( './policy_env_vars.js' );
var typescriptEnvVars = require( './typescript_env_vars.js' );


// FUNCTIONS //

/**
* Creates an environment variable string.
*
* @private
* @param {string} name - variable name
* @param {string} value - variable value
* @returns {string} environment variable string
*
* @example
* var out = env( 'ALIAS', 'acosd' );
* // returns 'ALIAS=\'acosd\''
*/
function env( name, value ) {
	return name + '=\'' + escapeBashString( value ) + '\'';
}


// MAIN //

/**
* Builds an array of environment variable strings for a given function.
*
* @private
* @param {string} basePkg - base package path
* @returns {Array<string>} array of environment variable strings
*
* @example
* var out = buildEnvVars( '@stdlib/math/base/special/acosd' );
* // returns [...]
*/
function buildEnvVars( basePkg ) {
	var outputPolicyPhrase;
	var outputElementType;
	var inputPolicyPhrase;
	var complexLikeImport;
	var inputElementType;
	var scalarKernelPath;
	var outputNdarray;
	var ndarrayImport;
	var outputDtypeTs;
	var outputDtypes;
	var templateVars;
	var inputNdarray;
	var readmeAssign;
	var exampleVals;
	var inputDtypes;
	var exampleRes;
	var moduleDesc;
	var readmeMain;
	var readmePkg;
	var baseAlias;
	var funcData;
	var keywords;
	var testDesc;
	var mainDesc;
	var pkgDesc;
	var pkgDeps;
	var param;
	var alias;
	var envs;
	var keys;
	var o;
	var i;

	o = DATA[ basePkg ];
	alias = o.alias;
	param = o.parameters[ 0 ];
	baseAlias = o.base_alias || o.alias;
	funcData = FUNCTION_DATABASE[ baseAlias ] || FUNCTION_DATABASE[ alias ];

	pkgDesc = 'Compute the ' + o.short_desc + ' for each element in an ndarray.';
	moduleDesc = 'Compute the ' + o.short_desc + ' for each element in an ndarray.';
	mainDesc = 'Computes the ' + o.short_desc + ' for each element in an ndarray.';
	testDesc = 'computes the ' + o.short_desc + ' for each element in an ndarray';
	readmePkg = readmeEnvVars.readmePkgDescEnvVar( o.short_desc, basePkg );
	readmeMain = readmeEnvVars.readmeMainDescEnvVar( o.short_desc, basePkg );
	readmeAssign = readmeEnvVars.readmeAssignDescEnvVar( o.short_desc, basePkg );

	scalarKernelPath = '@stdlib/math/base/special/' + alias;

	keywords = o.keywords || [];
	if ( o.extra_keywords ) {
		append( keywords, o.extra_keywords );
	}

	inputDtypes = funcData.input_dtypes;
	outputDtypes = funcData.output_dtypes;
	exampleVals = jsExampleEnvVars.jsExampleValues2x2EnvVar( param.example_values );
	exampleRes = jsExampleEnvVars.jsExampleResults2x2EnvVar( param.example_values, alias, outputDtypes );
	outputPolicyPhrase = policyEnvVars.outputPolicyPhraseEnvVar( funcData.policies.output );
	inputPolicyPhrase = policyEnvVars.inputPolicyPhraseEnvVar( funcData.input_dtypes );
	outputDtypeTs = typescriptEnvVars.outputDtypeTypeScript( funcData.output_dtypes );
	inputElementType = typescriptEnvVars.elementType( inputDtypes );
	outputElementType = typescriptEnvVars.elementType( outputDtypes );
	complexLikeImport = typescriptEnvVars.complexLikeImport( inputDtypes, outputDtypes );

	ndarrayImport = ndarrayEnvVars.ndarrayImportTypesEnvVar( inputDtypes, outputDtypes );
	inputNdarray = ndarrayEnvVars.inputNdarrayTypeEnvVar( inputDtypes );
	outputNdarray = ndarrayEnvVars.outputNdarrayTypeEnvVar( outputDtypes );
	pkgDeps = pkgDepsEnvVar( baseAlias );
	templateVars = generateTemplateVars( alias );

	envs = [
		aliasEnvVar( alias ),
		pkgEnvVar( alias ),
		env( 'PKG_PATH', 'stdlib/math/special' ),
		env( 'PKG_LINK_SUFFIX', basePkg.replace( /^@/, '' ) ),
		env( 'DESC', o.short_desc ),
		env( 'PKG_DESC', pkgDesc ),
		env( 'MODULE_DESC', moduleDesc ),
		env( 'MAIN_DESC', mainDesc ),
		env( 'TEST_DESC', testDesc ),
		assignDescEnvVar( pkgDesc ),
		readmePkg,
		readmeMain,
		readmeAssign,
		env( 'SCALAR_KERNEL_PATH', scalarKernelPath ),
		prngEnvVars( param.rand ),
		env( 'KEYWORDS', keywords.join( ',' ) ),
		env( 'YEAR', currentYear().toString() ),
		env( 'COPYRIGHT', 'The Stdlib Authors' ),
		exampleVals,
		exampleRes,
		ndarrayImport,
		inputNdarray,
		outputNdarray,
		pkgDeps,
		env( 'INPUT_DTYPES', funcData.input_dtypes ),
		env( 'OUTPUT_DTYPES', funcData.output_dtypes ),
		env( 'OUTPUT_POLICY', funcData.policies.output ),
		env( 'CASTING_POLICY', funcData.policies.casting ),
		env( 'OUTPUT_POLICY_PHRASE', outputPolicyPhrase ),
		env( 'INPUT_POLICY_PHRASE', inputPolicyPhrase ),
		env( 'OUTPUT_DTYPE_TS', outputDtypeTs ),
		env( 'INPUT_ELEMENT_TYPE', inputElementType ),
		env( 'OUTPUT_ELEMENT_TYPE', outputElementType ),
		env( 'COMPLEX_LIKE_IMPORT', complexLikeImport ),
		env( 'PRIMARY_DTYPE', funcData.primary_dtype ),
		env( 'PRIMARY_NDARRAY_TYPE', funcData.primary_dtype + 'ndarray' )
	];

	keys = objectKeys( templateVars );
	for ( i = 0; i < keys.length; i++ ) {
		envs.push( env( keys[ i ], templateVars[ keys[ i ] ] ) );
	}

	return envs;
}


// EXPORTS //

module.exports = buildEnvVars;
